/* Customer information and illustrative workflows. No live customer actions. */
const originalHome=pages.home;
const pageHead=(label,title,copy)=>`<section class="page-hero"><div class="wrap"><a class="breadcrumb" href="#/platform">AyudaGrow / Explore</a><span class="eyebrow">${label}</span><h1>${title}</h1><p>${copy}</p></div></section>`;
const section=(body,cls='')=>`<section class="section ${cls}"><div class="wrap">${body}</div></section>`;
const cardList=items=>`<div class="feature-grid">${items.map(([title,copy])=>`<article class="feature"><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div>`;
const journeyBar=items=>`<ol class="journey-bar">${items.map((v,i)=>`<li><span>0${i+1}</span>${v}</li>`).join('')}</ol>`;
const linkCards=items=>`<div class="explore-grid">${items.map(([path,kicker,title,copy])=>`<a href="#/${path}" class="explore-card"><span class="eyebrow">${kicker}</span><h3>${title}</h3><p>${copy}</p><span class="explore-arrow">→</span></a>`).join('')}</div>`;
const scopeNote=copy=>`<aside class="scope-note"><strong>Built around an agreed setup.</strong><p>${copy}</p></aside>`;
const persona=(kind)=>{let info={danielle:[danielle,'Danielle · Salon owner'],marcus:[marcus,'Marcus · B2B supplier'],elena:[elena,'Elena · Events & catering']}[kind];return `<figure class="portrait context-persona">${info[0]}<figcaption class="person-label">${info[1]}</figcaption></figure>`};
const visual=kind=>window.AyudaVisuals?.[kind]?.()||'<p>Illustrative workflow.</p>';
const capabilityRoutes={customers:'crm',capture:'lead-capture',conversations:'inbox',appointments:'appointments',pipeline:'consultative-sales',automation:'automation',marketing:'marketing',reputation:'reputation',payments:'commerce',learning:'learning',insights:'reporting',ai:'ai',connections:'integrations'};
const coreLinks=[['inbox','CONVERSATIONS','Many channels.<br>One place to respond.','Bring context together and reply through the customer’s original channel.'],['ai','AI + YOUR TEAM','Give AI a useful job.','Start with approved information, clear boundaries and a human next step.'],['follow-up','CONSISTENCY','Keep the next action visible.','Turn enquiries and quotes into assigned follow-up, not forgotten intentions.'],['reactivation','CUSTOMER GROWTH','Start a relevant new conversation.','Reconnect with suitable past customers, with consent and a reason to return.']];
pages.home=()=>originalHome().replace('<section class="integrations">',`${section(`<div class="section-head"><div><span class="eyebrow">A closer look / the unified inbox</span><h2>Different channels.<br>One connected conversation.</h2></div><p>See an enquiry arrive, reach your team and receive a reply through the same channel.</p></div>${visual('inbox')}<div class="visual-next"><a class="textlink" href="#/inbox">Explore the unified inbox <span>→</span></a><p class="micro">Illustrative channel journey. Supported connections and messaging permissions are confirmed for your setup.</p></div>`,'inbox-home')}<section class="integrations">`).replace('href="#/use-cases"><div class="path-copy"><span class="eyebrow">Consultative sales','href="#/consultative-sales"><div class="path-copy"><span class="eyebrow">Consultative sales').replace('href="#/use-cases"><div class="path-copy"><span class="eyebrow">Appointment-based businesses','href="#/appointments"><div class="path-copy"><span class="eyebrow">Appointment-based businesses');
pages.platform=()=>pageHead('The connected platform','AI at the front.<br>Context all the way through.','Bring AI support, customer conversations, sales activity and repeatable next steps into one connected way of working.')+section(linkCards(coreLinks))+section(`<div class="section-head"><div><span class="eyebrow">Start with the customer’s message</span><h2>Less switching.<br>More context.</h2></div><p>The inbox connects the conversation. CRM keeps the customer history. Your team owns the relationship.</p></div>${visual('inbox')}`,'how')+section(`<div class="how-layout"><div><span class="eyebrow">Keep the foundations</span><h2>Customer records.<br>Clear next actions.<br>Repeatable workflows.</h2><p>AI becomes more useful when the information and process around it are organised. Keep contact details, conversation history, owners and opportunity stages connected.</p><a class="textlink" href="#/crm">Explore the CRM foundation →</a></div>${demo()}</div>`)+section(`<div class="section-head"><h2>The wider platform.<br>Only what your business needs.</h2><p>Explore the full capability catalogue. Platform availability is separate from what is included and configured in your engagement.</p></div>${linkCards([['solutions','CAPABILITY CATALOGUE','Explore all 13 areas.','From lead capture and reputation to payments, communities and reporting.'],['support','THE PEOPLE BEHIND IT','Setup, training and support.','A connected system needs a practical process and a team that can use it.']])}`,'how')+cta();
pages.inbox=()=>pageHead('Unified inbox','Connected channels.<br>A shared place to respond.','Customers reach out in different places. Give your team a clearer way to see the conversation, keep its context and take the next step.')+section(`${visual('inbox')}<p class="micro visual-disclosure">Illustrative connection design, not a live product screenshot. WhatsApp, Instagram DM, Facebook DM, email and webchat are shown as the intended channel journey. Actual availability, account eligibility, permissions, response windows and usage charges must be confirmed before activation.</p>`,'inbox-focus')+section(`<div class="section-head"><h2>One inbox.<br>The customer’s chosen channel.</h2><p>An incoming Instagram DM stays an Instagram conversation. The response follows the same route back, rather than switching the customer to another channel.</p></div>${journeyBar(['Message arrives','Context stays together','AI assists or team replies','Reply returns to its origin'])}${cardList([['Respond with context','See supported conversation history and customer details together. A colleague can pick up the thread without making the customer start again.'],['Know who owns the reply','Assign a person, identify conversations needing attention and create a clear next action. A shared inbox should make responsibility clearer.'],['Use AI within agreed boundaries','Configure routine questions and approved information, with a clear handoff when the customer needs personal attention. Human review and takeover remain part of the design.'],['Keep the next step connected','A conversation can lead to a booking, quotation, assigned task or opportunity stage, depending on the workflow you agree.']])}`,'how')+section(`<div class="how-layout">${persona('danielle')}<div><span class="eyebrow">An illustrative day with Danielle</span><h2>A question arrives<br>while she’s with a client.</h2><p>Danielle runs a hair salon and beauty studio. Enquiries come through messaging channels while her team is serving customers. A shared conversation and a visible owner help the team respond with the right context.</p><p>The example is about the workflow, not a claim that Danielle is a paying customer or that every reply is automated.</p><a href="#/appointments" class="textlink">Explore appointment-based businesses →</a></div></div>`)+cta();
pages.ai=()=>pageHead('Practical AI support','Start with a clear job.<br>Keep people in control.','Use AI to help with routine questions, initial enquiry handling and useful drafts, grounded in information your business approves.')+section(`<div class="ai-orbit"><span class="eyebrow">YOUR BUSINESS KNOWLEDGE</span><div class="ai-orbit-core">✦<strong>AI support</strong><small>Useful, bounded, connected</small></div><div class="ai-orbit-labels"><span>Approved answers</span><span>Clear handoffs</span><span>Human judgement</span></div></div>${journeyBar(['Define the job','Provide approved information','Test the boundaries','Review and improve'])}`)+section(cardList([['Answer agreed routine questions','Help customers find straightforward information about your business. Confirm what the assistant may answer and when it must ask a person.'],['Help organise the first enquiry','Capture relevant details and route the conversation toward an appropriate next step. Initial qualification supports, rather than replaces, the team’s judgement.'],['Prepare useful drafts','Support replies, content and follow-up with a starting point that your team can check for accuracy, tone and context.'],['Connect AI to the workflow','Where available and configured, connect approved actions to customer records, calendars and tasks. Do not treat platform access as a fully configured agent.']]),'how')+section(`<div class="section-head"><h2>The guardrails<br>are part of the setup.</h2></div><div class="guardrail-grid"><div><b>Knowledge</b><p>Use approved business information and a process for keeping it current.</p></div><div><b>Boundaries</b><p>Decide which topics, commitments and actions need a person.</p></div><div><b>Handoff</b><p>Give the team the conversation and context when they take over.</p></div><div><b>Review</b><p>Test real situations and revisit behaviour as the business changes.</p></div></div>${scopeNote('AI tools, model usage, channels, limits and costs vary. Voice AI and advanced agents require separate assessment. Medical and dental examples are administrative only, not clinical advice or records.')}`)+cta();
pages['follow-up']=()=>pageHead('Follow-up & reminders','A good conversation<br>deserves a next step.','Keep quotations, enquiries and appointments moving with clear ownership, timely reminders and a shared view of what needs attention.')+section(visual('followup'))+section(`<div class="how-layout"><div><span class="eyebrow">From memory to a repeatable process</span><h2>See what’s due.<br>Know who owns it.</h2><p>A reminder is useful when it is connected to the customer, the last conversation and the action needed. Agree the timing and conditions, then make the next step visible to the right person.</p></div>${persona('marcus')}</div>${cardList([['Assign an owner and due date','Give the enquiry or quote a responsible person and a meaningful next action. Make the handoff explicit.'],['Follow the stage of the sale','Different situations need different timing. A fresh enquiry, a proposal awaiting review and an existing customer need different follow-through.'],['Stop when the situation changes','Review the configured stop conditions when a customer replies, books, declines or opts out, so messages remain relevant.'],['Keep the team informed','Show tasks, opportunity stages and conversation history together. AI can assist with a draft; a person can handle the decision.']])}`,'how')+section(scopeNote('Illustrative workflow. Customer-facing messages require the right permissions, approved copy and channel rules. Internal reminders and customer messages are different actions; both need an agreed configuration.'))+cta();
pages.reactivation=()=>pageHead('Customer & opportunity reactivation','Past interest.<br>A relevant new conversation.','Follow up on past customers, older enquiries and outstanding quotes with a relevant reason and appropriate permission.')+section(`<div class="rf-reactivation-examples" aria-label="Possible reactivation opportunities"><span>Past customers</span><span>Older enquiries</span><span>Outstanding quotes</span><b>Relevant reason + permission → Thoughtful follow-up</b></div>${visual('reactivation')}`)+section(`<div class="section-head"><h2>A thoughtful reason<br>to get back in touch.</h2><p>Reactivation starts with relevance and permission. It is an opportunity to restart a relationship, not a guaranteed sale.</p></div>${journeyBar(['Choose eligible contacts','Find a relevant reason','Send an approved message','Route responses to your team'])}${cardList([['Choose the right group','Use appropriate customer history, tags and activity to identify a suitable audience. Exclude opt-outs, invalid details and people who should not receive the message.'],['Make the reason useful','A return visit, a service update or a relevant offer should fit the relationship. AI can help prepare wording for review, not invent personal facts.'],['Keep replies connected','Bring supported responses back into the shared conversation and give interested customers a clear human next step.'],['Review what actually happened','Look at responses, opportunities and opt-outs. Adjust timing and content based on evidence, without assuming every quiet contact is ready to buy.']])}`,'how')+section(`<div class="how-layout">${persona('elena')}<div><span class="eyebrow">An illustrative event business</span><h2>Remember the relationship.<br>Respect the timing.</h2><p>Elena’s events and catering business has past clients with different occasions and needs. A relevant follow-up begins with the relationship and the information she is allowed to use, then gives a person ownership of any reply.</p><a class="textlink" href="#/consultative-sales">See the consultative sales journey →</a></div></div>${scopeNote('Reactivation requires appropriate consent, contact quality and channel compliance. Delivery costs and AI usage may apply. No response, conversion or revenue outcome is guaranteed.')}`)+cta();
pages.automation=()=>pageHead('Automation & connected workflows','Let repeatable work<br>follow a clear plan.','Connect repeatable tasks with clear triggers, conditions and actions. Add AI where it has an agreed role.')+section(visual('followup'))+section('<h2 class="sr-only">Where workflow automation can help</h2>'+cardList([['Capture and assign','Route a new enquiry to an appropriate owner and make the first response visible.'],['Nurture and follow up','Build an agreed sequence with relevant messages, internal tasks and clear stop conditions.'],['Support appointments','Connect booking status, reminders and follow-up so administrative work is easier to track.'],['Reconnect thoughtfully','Use eligible segments and relevant reasons to restart conversations with past customers.']]),'how')+section(`${linkCards([['follow-up','FOLLOW-THROUGH','Make the next action visible.','Explore reminders and assigned tasks.'],['reactivation','REACTIVATION','Reconnect with relevance.','Explore a consent-aware customer journey.']])}${scopeNote('Triggers, conditions, delivery channels and permissions are configured for your business. Premium workflow actions, external services and AI usage can incur additional charges.')}`)+cta();
const rolePanel=()=>`<div class="role-switch"><div role="group" aria-label="Choose your team role"><button data-team-role="owner" aria-pressed="true">Business owner</button><button data-team-role="manager" aria-pressed="false">Sales manager</button><button data-team-role="rep" aria-pressed="false">Sales representative</button></div><div id="team-role-copy" aria-live="polite"><h3>See the work behind the growth.</h3><p>Understand where opportunities stand, where follow-up slows and what needs attention. Give your team more time for customers and a clearer basis for planning.</p></div></div>`;
pages['consultative-sales']=()=>pageHead('B2B & consultative sales','Keep the relationship.<br>Move the decision forward.','Bring initial enquiries, discovery, quotations, proposals and follow-up into a visible process for your sales team.')+section(`<div class="how-layout"><div>${journeyBar(['Enquiry & qualification','Discovery','Proposal or quotation','Decision & next step'])}<p>AI can support the first response and agreed routine questions. People lead discovery, advice, negotiation and closing.</p></div>${persona('marcus')}</div>`)+section(`<div class="section-head"><h2>Longer sales cycles.<br>A clearer shared picture.</h2></div>${cardList([['Qualification with context','Capture what the prospective customer needs, relevant timing and the information needed for a useful conversation.'],['A pipeline that fits your sales process','Agree stages and ownership so every opportunity has a place, a responsible person and a next action.'],['Proposals that do not disappear','Keep quotation and proposal activity linked to the customer. Document and e-signature capabilities depend on agreed access and configuration.'],['Visibility for the whole team','Use current records and activity to review stalled opportunities, coach follow-through and plan the next conversation.']])}${rolePanel()}`,'how')+section(`${visual('followup')}<p class="micro">Illustrative quotation follow-up. No autonomous deal-closing or guaranteed revenue is implied.</p>`)+cta();
pages.appointments=()=>pageHead('Appointment-based businesses','From the first question<br>to the next visit.','Connect enquiries, bookings, reminders and follow-up around the customer experience, with practical AI support and a team ready to help.')+section(`<div class="how-layout">${persona('danielle')}<div><span class="eyebrow">A more connected working day</span><h2>Help the customer.<br>Keep the schedule in view.</h2><p>Keep enquiries and booking details together so staff can respond clearly, even on busy days.</p>${journeyBar(['Enquiry','Booking','Visit','Follow-up & return'])}</div></div>`)+section(cardList([['Make booking easier','Connect agreed booking calendars, availability and team scheduling. Confirm which services, staff and appointment rules belong in the setup.'],['Keep reminders relevant','Use configured confirmations and reminders to keep customers informed. Channel availability, consent and costs apply.'],['Respond to a cancellation','Make the changed appointment visible and create a suitable next step. Rebooking or filling a slot is a possible workflow, not a promised outcome.'],['Build the relationship after the visit','Keep appropriate preferences and follow-up context together, then invite a useful next step when the time is right.']]),'how')+section(`${visual('followup')}${scopeNote('Suitable examples include salons, beauty studios, wellness and other appointment-based services. Medical and dental workflows are administrative only; clinical advice, diagnosis and medical-record handling are outside this concept.')}`)+cta();
pages.crm=()=>pageHead('CRM & customer context','A shared memory<br>for your business.','Keep customer details, conversations, notes and opportunities connected so your team can pick up the story and follow through.')+section(`<div class="how-layout"><div><span class="eyebrow">People own the relationship</span><h2>The system keeps<br>the context together.</h2><p>CRM means customer relationship management. It gives the team a shared place for useful information, rather than leaving the customer’s history scattered across individual inboxes and notebooks.</p><a class="textlink" href="#/learn">New to CRM? Start here →</a></div>${demo()}</div>`)+section(cardList([['Customer records','Organise appropriate contact details, companies, tags, notes and custom fields around your business needs.'],['Conversations and tasks','Keep history, ownership and follow-up visible so a colleague can understand what happened and what should happen next.'],['Opportunities and pipeline','Track stages, value, owner, expected close date and next action. Review inactive deals, current workload and progress. Reliable reporting depends on records being kept current.'],['A useful foundation for AI','Give approved AI workflows relevant business context, with permissions and boundaries agreed during setup.']]),'how')+cta();
pages.learn=()=>pageHead('What is CRM?','Your customers,<br>connected.','CRM stands for customer relationship management. Think of it as a shared customer memory, with the next step attached.')+section(`<div class="editorial"><span class="eyebrow">Plain English, practical purpose</span><h2>“Where did we leave<br>that conversation?”</h2><p>A CRM helps the team answer that question. It can keep contact details, useful notes, conversations, appointments and sales opportunities in one organised place.</p><p>It is more than a list of names. The value comes from knowing what happened, who is responsible and what should happen next.</p></div>${journeyBar(['Know the customer','Keep the context','See the next step','Follow through'])}`)+section(cardList([['For an appointment-based business','An enquiry leads to a booking, a visit and an appropriate follow-up. The team can see where the customer is in that journey.'],['For a B2B sales team','Discovery, quotations, proposals and decisions can be organised into stages, with an owner and follow-up date.'],['For the business owner','A shared view makes it easier to understand open opportunities and work needing attention, instead of relying on disconnected updates.'],['For AI and automation','Organised information and clear rules support useful assistance. AI does not replace the people who understand the customer or make important decisions.']]),'how')+section(`<div class="editorial"><h2>Start simply.<br>Build the habit.</h2><p>Choose the information your team actually needs. Agree who updates it and how follow-up is handled. Practise a small set of everyday tasks before adding complexity.</p><p>AyudaGrow combines the platform with strategy, setup, training and ongoing support. The scope is agreed around your business.</p></div>${linkCards([['crm','THE FOUNDATION','Explore the customer workspace.','Records, conversations and opportunities.'],['support','PRACTICAL HELP','See how we help you start.','Setup and training for everyday use.']])}`)+cta();
const outcomes=[
['convert-more-leads','Capture more of the interest you already earn.','Give new enquiries a useful response and a clear route forward.',['Capture the enquiry and source','Assign the first response','Follow up with context'],[['lead-capture','Capture the enquiry'],['ai','Explore AI support'],['inbox','See the unified inbox'],['follow-up','Keep the next step moving']],'A team that can see new enquiries and who owns them.','A customer who understands what happens next.','Review response handling, enquiry progression and opportunities created.'],
['improve-sales-follow-up','Keep the conversation moving.','Make next steps, due dates and ownership part of the sales routine.',['Agree the next action','Configure suitable reminders','Hand over with context'],[['follow-up','Explore follow-up reminders'],['consultative-sales','See the sales journey'],['automation','Explore configured workflows']],'Less time reconstructing what happened.','A more consistent conversation with your business.','Review overdue tasks, stalled quotations and completed follow-up.'],
['manage-sales-opportunities','See where the opportunities stand.','Give sales activity a shared structure that helps people prioritise.',['Use a shared pipeline','Review stalled and ready opportunities','Act on current information'],[['crm','Organise the CRM & pipeline'],['reporting','Explore reporting & forecasting']],'A clearer view of owners, workload and the next decision.','Fewer repeated questions when the conversation changes hands.','Review record completeness, stage movement and next-action coverage.'],
['book-more-appointments','Make the next appointment easier to arrange.','Connect the enquiry, availability and follow-up around a useful booking process.',['Help the customer find a time','Confirm the agreed appointment','Handle reminders and changes'],[['appointments','Explore the appointment journey'],['inbox','Keep enquiries connected'],['follow-up','Explore reminders & follow-up']],'Less disconnected scheduling administration.','Clearer information before and after the visit.','Review booking progression, changes and follow-up activity.'],
['improve-customer-communication','Reply with the whole story.','Bring supported conversations and customer context together.',['Connect the agreed channels','Keep useful history attached','Reply or hand over with context'],[['inbox','Explore the unified inbox'],['ai','See AI support & human handoff'],['crm','Keep the customer context']],'A shared place to see the conversation and take responsibility.','Less need to repeat the same details to another colleague.','Review handoffs, conversation ownership and response handling.'],
['generate-more-reviews','Make feedback part of the follow-through.','Invite feedback at an appropriate time and keep all customer experiences in view.',['Choose an appropriate completed-service trigger','Send a consistent review invitation','Monitor feedback and respond'],[['reputation','Explore reputation & Google profile management'],['appointments','See the completed-visit journey'],['automation','Explore configured review workflows']],'A repeatable way to see what customers are telling you.','An invitation to share an honest experience.','Review invitations, responses and follow-through without inventing ratings or filtering out unhappy customers.'],
['reactivate-customers','Give past interest a relevant next chapter.','Reconnect with eligible past customers, older enquiries and outstanding quotes through useful, permission-aware communication.',['Choose an eligible segment','Prepare a relevant approved message','Give replies a person and next step'],[['reactivation','Explore reactivation opportunities'],['automation','Configure suitable follow-up'],['inbox','Bring replies into the shared inbox']],'An organised way to follow up on renewed interest.','Communication that reflects the relationship and respects preferences.','Review relevant responses, new opportunities, opt-outs and stop conditions.']
];
const outcomeExamples={
 'convert-more-leads':['A useful first response','A supplier receives an enquiry while the team is serving customers. Capture the request, use approved information for suitable questions and give a person ownership of the quotation.'],
 'improve-sales-follow-up':['The quotation has a next step','After sending a proposal, the account manager records a follow-up date and the buyer’s open question. A colleague can see what is due without searching through private messages.'],
 'manage-sales-opportunities':['A quiet deal gets attention','At the weekly pipeline review, a manager spots a proposal with no recent activity. The owner checks the buyer’s status, updates the expected date and records the next action.'],
 'book-more-appointments':['A change does not lose the conversation','A customer needs to move a salon appointment. The team sees the original enquiry, checks suitable availability and confirms the change through the agreed process.'],
 'improve-customer-communication':['A colleague picks up the thread','A customer asks a follow-up question on a connected messaging channel. The next team member sees the supported history and continues the conversation without asking for the same details again.'],
 'generate-more-reviews':['The visit becomes an invitation','After a completed service, an eligible customer receives a neutral invitation to share an honest review. The team reviews feedback and routes any concern to the person who can help.'],
 'reactivate-customers':['An older quote, a useful reason','A customer previously requested a quote but paused the decision. With appropriate permission and a relevant reason, the team checks whether help is still needed, respects opt-outs and assigns any reply.']
};
for(const [key,title,intro,steps,links,team,customer,measure] of outcomes){pages['solutions/'+key]=()=>pageHead('Business outcomes',title,intro)+section('<h2 class="sr-only">Benefits and an illustrative example</h2>'+journeyBar(steps)+cardList([['For your team',team],['For your customers',customer]])+`<aside class="ag-outcome-example"><span class="eyebrow">A practical example / illustrative</span><h3>${outcomeExamples[key][0]}</h3><p>${outcomeExamples[key][1]}</p></aside>`)+section(`<div class="editorial"><span class="eyebrow">What to review</span><h2>Look for useful progress.<br>Measure the real result.</h2><p>${measure}</p><p>Intended improvements, not promised results. Agree what improvement to measure.</p></div><div class="ag-outcome-related"><h3>Explore the supporting tools.</h3>${key==='generate-more-reviews'?'<p class="micro">Review-request tools and hands-on Google profile management are different scopes. The managed service is additional and agreed separately.</p>':''}<div class="related-links">${links.map(([url,text])=>`<a class="textlink" href="#/${url}">${text} →</a>`).join('')}</div></div>`,'how')+cta()}
// Scan first, explore second: the same approachable card pattern for outcomes and tools.
