const solutionIcon=(key)=>`<span class="ag-card-icon${key==='ai'?' ag-card-icon-ai':''}" aria-hidden="true">${key==='ai'?'<img src="assets/mascot-laptop.webp" alt="">':`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${solutionIcons[key]}</svg>`}</span>`;
