 'convert-more-leads':['Convert More Enquiries','capture'],
 'improve-sales-follow-up':['Follow Up with Confidence','followup'],
 'manage-sales-opportunities':['See Your Sales Pipeline','sales'],
 'book-more-appointments':['Simplify Appointments','calendar'],
 'improve-customer-communication':['Connect Conversations','inbox'],
 'generate-more-reviews':['Build Your Reputation','star'],
