pages.home=()=>homeWithInbox().replace('AI + automation. People + possibility.','Your business knowledge. Your AI assistant.').replace('Turn more enquiries into customers with AI and automation, backed by practical setup, training and ongoing support.','A customized AI assistant that helps answer enquiries, qualify interest and move customers toward the next step, backed by your business knowledge and practical support.').replace('href="#/platform" class="textlink">See how it works','href="#/ai" class="textlink">Meet your AI assistant').replace('<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Good opportunities deserve better',`${section(`<div class="section-head"><div><span class="eyebrow">The AI assistant, built around your business</span><h2><span class="heading-lead">Your Business knowledge.</span><br>A useful conversation.<br>A clear next step.</h2></div><p>Start with approved information and clear boundaries, then configure your assistant for the channels and jobs you need.</p></div>${visual('ai')}<div class="visual-next"><a class="textlink" href="#/ai">Explore your AI employee →</a><p class="micro">Illustrative workflow. Channels, actions and human handoff are configured; knowledge improves through review and updates.</p></div>`,'ai-home')}<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Good opportunities deserve better`);
pages.ai=()=>pageHead('Your customized AI assistant','Knows your business.<br>Helps your customers.<br>Works with your team.','Build an AI assistant around approved business information, useful tasks and clear boundaries, so more enquiries have a helpful next step, including outside your team’s working hours.')+section(`${visual('ai')}<div class="visual-next"><p class="micro">An illustration, not a live agent. The final assistant is configured and tested for your business.</p></div>`,'ai-focus')+section(`<div class="section-head"><div><span class="eyebrow">A useful role in everyday business</span><h2>More than a greeting.<br>A practical next step.</h2></div><p>Choose the jobs that fit your process. Keep important decisions and commitments with the people responsible for them.</p></div>${cardList([['Answer customer questions','Use approved business knowledge to respond to routine questions about your services, process and other agreed information. Define when a person should take over.'],['Screen and qualify enquiries','Collect relevant information and apply your agreed qualification criteria so the team has useful context. This supports human decisions; it is not unrestricted authority to accept or reject people.'],['Help arrange appointments','Use configured calendars and booking rules where supported. Confirm availability, services and what the assistant may change.'],['Share approved information','Use supported rich-message features to share approved files, or configured workflows to send emails and attachments. Availability depends on the channel and setup.'],['Activate agreed tasks','Trigger configured workflows, notifications or follow-up tasks within defined permissions. The assistant can support several functions without being authorised to do anything it chooses.'],['Keep the conversation moving after hours','Configured AI can handle routine enquiries when your team is away and preserve context for follow-up. Availability depends on services and setup; no missed-lead, uptime or response guarantee is implied.']])}`,'how')+section(`<div class="how-layout"><div><span class="eyebrow">Business knowledge, maintained</span><h2>Consistent information.<br>Connected experiences.</h2><p>Approved knowledge sources can be attached to chat and voice agents. Channel and agent configuration still matter: a shared source does not automatically activate every channel or make every action available everywhere.</p><p>Review conversations, identify unanswered questions and update the knowledge base. The improvement loop is deliberate and supervised, not a claim that the assistant teaches itself from every interaction.</p></div><div class="knowledge-stack"><article><span>01</span><b>Your approved information</b><p>Services, processes, answers and relevant business content.</p></article><article><span>02</span><b>Configured assistants</b><p>The channels, tasks and permissions you agree.</p></article><article><span>03</span><b>Ongoing review</b><p>Knowledge gaps, answer checks and approved updates.</p></article></div></div>`)+section(`<div class="section-head"><div><span class="eyebrow">Text and voice</span><h2>Meet customers where<br>your setup supports them.</h2></div><p>Channel support is a capability. Enabling it for your business involves account access, eligibility, configuration and applicable charges.</p></div><div class="channel-capabilities"><article><span class="eyebrow">CONVERSATIONAL CHANNELS</span><h3>Messages, connected.</h3><p>Conversation AI supports WhatsApp, Instagram DM, Facebook Messenger, web/live chat and inbound email, configured individually.</p><a class="textlink" href="#/inbox">See the connected inbox →</a></article><article><span class="eyebrow">VOICE AI</span><h3>A voice for incoming calls.</h3><p>Configure voice agents for supported telephone calls. WhatsApp Calling with Voice AI is also possible, subject to eligible numbers, account requirements and setup.</p><p class="micro">This illustration does not indicate that your account is enabled. Do not assume universal WhatsApp calling, outbound WhatsApp AI calls or unrestricted voice availability.</p></article></div>${journeyBar(['Approve the knowledge','Configure channels & tasks','Test replies & handoffs','Review and maintain'])}`,'how')+section(`<div class="how-layout">${persona('elena')}<div><span class="eyebrow">An illustrative after-hours enquiry</span><h2>A question tonight.<br>Context for the team tomorrow.</h2><p>Someone asks Elena’s events business about an occasion while her team is away. A configured assistant can answer approved questions, collect relevant details and route the conversation for the team’s next step.</p><p>Human handoff can assign and notify the team and pause the bot. It does not promise that a person is immediately available.</p></div></div><details class="source-disclosure"><summary>Capability scope and setup boundaries</summary><p>Product capability does not establish what is included or activated in your AyudaGrow engagement. We agree the supported channels, permissions and tasks for your business.</p><p>AI usage, channel charges and additional features may apply. Confirm operating limits, support arrangements and a fallback plan before activation.</p><a class="textlink" href="#/contact">Discuss your AI setup →</a></details>`)+cta();
const platformBeforeLoop=pages.platform;
pages.platform=()=>platformBeforeLoop().replace('AI at the front.<br>Context all the way through.','Your AI assistant.<br>A connected growth system.').replace('<section class="section"><div class="wrap"><div class="explore-grid">',`<section class="section"><div class="wrap"><div class="route-intro"><span class="eyebrow">The Ayuda Growth Loop</span><h2>One relationship.<br>More than one opportunity.</h2><p>Keep the full customer journey connected, from first interest to returning customers. AI helps with defined work inside that journey; your team owns the relationship.</p><div class="growth-loop"><span>Attract &amp; capture</span><span>Follow up &amp; nurture</span><span>Convert &amp; close</span><span>Delight &amp; grow</span><span>Reactivate</span></div></div><div class="explore-grid">`);
