const appointmentsBase=pages.appointments;pages.appointments=()=>appointmentsBase().replace('A more connected working day','A more connected working day').replace(journeyBar(['Enquiry','Booking','Visit','Follow-up & return']),journeyBar(['Enquiry','Appointment','Quote, if needed','Service completed','Review','Repeat visit']));

